        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        int M = fs.nextInt();

        int[] T = new int[N];
        for (int i = 0; i < N; i++) T[i] = fs.nextInt();

        int[] F = new int[M];
        for (int i = 0; i < M; i++) F[i] = fs.nextInt();

        if (N <= M) {
            System.out.println(0);
            return;
        }

        Arrays.sort(T);
        int K = N - M;

        long lo = 1;
        long hi = 10000L * N;

        while (lo < hi) {
            long mid = (lo + hi) >>> 1;
            long cnt = 0;
            for (int f : F) {
                cnt += mid / f;
                if (cnt >= K) break;
            }
            if (cnt >= K) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }

        long x = lo;

        long[] vals = new long[N];
        int idx = 0;
        for (int f : F) {
            for (long v = f; v <= x; v += f) {
                vals[idx++] = v;
            }
        }

        Arrays.sort(vals, 0, idx);

        long ans = 0;
        for (int p = 0; p < K; p++) {
            ans += vals[p] * T[K - 1 - p];
        }

        System.out.println(ans);
    }

